function initials(name){return name.split(' ').map(s=>s[0]).slice(0,2).join('');}
function age(l){const days=Math.max(0,Math.floor((Date.now()-l.created)/86400000));return days?days+'d ago':'Today';}
function scoped(){const cutoff=state.range==='all'?0:Date.now()-Number(state.range)*86400000;return leads.filter(l=>l.created>=cutoff);}
function metrics(items=scoped()){
 const won=items.filter(l=>wonStages.includes(l.stage)),lost=items.filter(l=>l.stage==='lost');
 return {total:items.length,won:won.length,rate:won.length+lost.length?Math.round(won.length/(won.length+lost.length)*100):0,pipeline:items.filter(l=>openStages.includes(l.stage)).reduce((n,l)=>n+l.value,0)};
}
function spark(idx,cyan=false){const lines=['M0 29C10 29 10 18 22 20S36 36 47 23S60 15 70 20S82 24 92 13S108 24 118 10S130 16 140 7S153 15 165 4','M0 30C12 30 12 24 24 25S35 13 46 20S58 30 70 19S83 8 94 15S107 22 118 12S133 21 142 10S155 18 165 6','M0 31C12 31 12 22 24 21S35 28 46 20S59 25 70 15S84 21 94 12S105 15 118 10S130 12 142 6S154 9 165 1','M0 29C10 18 17 24 27 16S40 27 50 19S62 32 72 22S83 10 95 16S109 27 120 18S133 10 143 14S156 22 165 10'];return `<svg class="sparkline" viewBox="0 0 165 40" preserveAspectRatio="none" aria-hidden="true"><path d="${lines[idx]}" stroke="${cyan?'#18badd':'#b4d52c'}"/></svg>`;}
function metricsHTML(){const m=metrics();const rows=[['Total Leads',m.total,'userplus','All leads in selected period','Includes every stage'],['Won Jobs',m.won,'briefcase','Includes active & completed jobs','Won, Work in Progress and Job Completed'],['Win Rate',m.rate+'%','target','Won ÷ closed opportunities','Won jobs divided by won and lost jobs'],['Pipeline Value',compact(m.pipeline),'dollar','Open sales opportunities only','New through Contract Signed; excludes production and closed jobs']];return `<div class="metrics">${rows.map((r,i)=>`<article class="metric"><span class="metric-info" title="${r[4]}">${I('info')}</span><div class="metric-head"><span class="metric-icon">${I(r[2])}</span><div><div class="metric-label">${r[0]}</div><div class="metric-number">${r[1]}</div></div></div><div class="metric-foot">${I(i===2?'target':'trend')}<span>${r[3]}</span></div>${spark(i,i%2===1)}</article>`).join('')}</div>`;}
function renderSidebar(){document.querySelector('#sidebar').innerHTML=`<a href="#dashboard" class="brand"><img src="./assets/xo-mascot.png" alt="XØ"><div class="brand-name">XAU <small>PRIME CRM</small></div></a><nav>${navItems.map((n,i)=>`${i===4?'<div class="nav-label">WORKSPACE</div>':i===9?'<div class="nav-label">GROWTH & INTELLIGENCE</div>':''}<a class="nav-item ${currentPage===n[0]?'active':''}" href="#${n[0]}" ${currentPage===n[0]?'aria-current="page"':''}>${I(n[2])}<span>${n[1]}</span>${n[0]==='leads'?`<span class="nav-count">${leads.length}</span>`:n[0]==='messages'?'<span class="tiny-dot" style="background:#13b8d5"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-item ${currentPage==='settings'?'active':''}" href="#settings">${I('settings')}<span>Settings</span></a><button class="xo-dock" data-action="agent" data-id="call"><img src="./assets/xo-mascot.png" alt=""><div><b>XØ Intelligence</b><small>Explore your AI team</small></div>${I('chevron')}</button><button class="profile" data-action="navigate" data-page="settings"><span class="avatar">BG</span><span>Bryan Gonzalez<small>Workspace admin</small></span>${I('down')}</button></div>`;}
