function miniBoard(){return `<div class="board-wrap" id="mini-board-scroll"><div class="mini-board">${stages.map(s=>{const ls=scoped().filter(l=>l.stage===s.id);return `<section class="mini-column" style="--stage-color:${s.color}"><div class="mini-column-head"><span>${s.name}</span><small>${ls.length}</small></div>${ls.slice(0,2).map(l=>`<button class="mini-lead" data-action="open-lead" data-id="${l.id}"><strong>${esc(l.name)}</strong><p>${esc(l.service)}</p><div><b>${compact(l.value)}</b><small>${esc(l.source)}</small></div></button>`).join('')}${ls.length===0?'<div class="empty-state">Ready for your next lead</div>':''}<button class="mini-add" data-action="add-lead" data-stage="${s.id}">${I('plus')}Add lead</button></section>`;}).join('')}</div></div>`;}
function aiPanel(){return `<aside class="panel ai-panel"><div class="section-head"><h2>XØ AI Agents</h2><span class="badge demo">Preview</span></div><div class="ai-art"><i class="orbit"></i><i class="orbit two"></i><img src="./assets/xo-mascot.png" alt="XØ, your XAU assistant"></div><p class="ai-intro">Your next move, already in motion.</p>${agentData.map(a=>`<button class="agent-tile" data-action="agent" data-id="${a.id}"><span class="agent-icon ${a.cyan?'cyan':''}">${I(a.icon)}</span><span><b>${a.name} <span class="badge cyan">Demo</span></b><p>${a.desc}</p></span>${I('chevron')}</button>`).join('')}<a class="text-button" href="#ai-agents">Explore your AI team ${I('arrow')}</a></aside>`;}
const samplePayments=[{name:'Kevin Ford',value:25300,month:0},{name:'Laura Bennett',value:17600,month:1},{name:'Charlotte Hall',value:17600,month:2},{name:'Logan Price',value:12400,month:3},{name:'Project deposit',value:3250,month:4},{name:'Milestone payment',value:7400,month:5}];
function revenueChart(){let vals=samplePayments.map(p=>p.value).reverse();if(state.revenue==='3')vals=vals.slice(-3);let sum=0;const cumulative=vals.map(v=>sum+=v);const total=sum;const max=Math.ceil(total/25000)*25000;const points=cumulative.map((v,i)=>[36+i*290/(vals.length-1),137-v/max*110]);const path='M'+points.map(p=>p.join(',')).join(' L');const area=path+` L326,145 L36,145Z`;const monthLabels=vals.map((_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-vals.length+1+i);return d.toLocaleDateString('en-US',{month:'short'});});return `<div class="revenue-number">${money(total)}</div><p class="revenue-note"><b>Payments received</b> · Sample financial activity</p><svg class="revenue-chart" viewBox="0 0 350 170" role="img" aria-label="Sample cumulative payments of ${money(total)} over the last ${vals.length} months"><defs><linearGradient id="revenueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#c7ee28" stop-opacity=".25"/><stop offset="100%" stop-color="#c7ee28" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line class="chart-grid" x1="35" x2="330" y1="${137-i*36}" y2="${137-i*36}"/><text x="0" y="${140-i*36}">$${Math.round(max*i/3/1000)}K</text>`).join('')}<path d="${area}" fill="url(#revenueFill)"/><path class="chart-draw" d="${path}" stroke="#cbed30" stroke-width="2.5" fill="none" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#d2f239"><title>${monthLabels[i]}: ${money(cumulative[i])} cumulative</title></circle><text x="${p[0]}" y="164" text-anchor="middle">${monthLabels[i]}</text>`).join('')}</svg><div class="rev-legend"><span><i></i>Cumulative collected</span><span>Separate from won contract value</span></div>`;}
const appointments=[{time:'9:00 AM',duration:'60 min',name:'Sarah Jones',task:'Roof inspection',kind:'On site',id:'lead-103'},{time:'12:30 PM',duration:'30 min',name:'Mark Carter',task:'Estimate review',kind:'Video call',id:'lead-105'},{time:'3:00 PM',duration:'45 min',name:'David Kim',task:'Project scope meeting',kind:'On site',id:'lead-104'}];
function appointmentHTML(){return appointments.map(a=>`<button class="appointment" data-action="open-lead" data-id="${a.id}"><span class="appointment-time">${a.time}<small>${a.duration}</small></span><span class="appointment-info"><b>${a.name}</b><p>${a.task}</p><span class="badge ${a.kind==='On site'?'green':'cyan'}">${a.kind}</span></span>${I('calendar')}</button>`).join('');}
function websiteMini(){return `<div class="website-mini" aria-label="Illustrative contractor website"><div class="site-browser"><i></i><i></i><i></i><span>lizmarconstructionllc.com</span></div><svg class="mini-house" viewBox="0 0 150 160" aria-hidden="true"><path d="m10 65 75-48 55 30-68 48Z" fill="#698074"/><path d="m10 65 62 30v60L10 124Z" fill="#354f40"/><path d="m72 95 68-48v78l-68 30Z" fill="#738676"/><path d="m82 95 17-11v26l-17 9Zm29-21 17-12v26l-17 11Z" fill="#cbe38c"/><path d="m20 86 20 10v26l-20-9Z" fill="#adc171"/><path d="m55 98 11 5v46l-11-5Z" fill="#192c1d"/></svg><div class="site-mini-copy"><small>LIZMAR CONSTRUCTION</small><h3>Built right.<br>Built to last.</h3><span>Get a free estimate ↗</span></div><div class="site-live-label"><i class="tiny-dot"></i>Website preview</div></div>`;}
function websitePanel(){return `<section class="panel website-panel"><div class="section-head"><h2>Website Pulse</h2><span class="badge demo">Sample stats</span></div><div class="website-content">${websiteMini()}<div class="pulse-stats"><div><small><i class="tiny-dot"></i>Active visitors</small><strong>18</strong></div><div><small>Visitors this month</small><strong>1,247</strong></div><div><small>Website leads</small><strong>${leads.filter(l=>l.source==='Website').length}</strong></div><a class="text-button" href="#website">View website insights ${I('arrow')}</a></div></div><p class="sample-note">Traffic is illustrative until your analytics is connected.</p></section>`;}
function renderDashboard(){main.innerHTML=demoBar()+`<div class="dashboard-grid"><div class="dash-main">${metricsHTML()}<section class="panel lead-flow"><div class="section-head"><div class="heading-group"><h2>Lead Flow</h2><span class="pill-label">${scoped().length} leads</span></div><a class="btn small" href="#leads">Open pipeline ${I('arrow')}</a></div>${miniBoard()}<div class="board-caption">${I('grip')}All eight stages · Open any card to review the next step</div></section></div>${aiPanel()}</div><div class="dashboard-bottom"><section class="panel revenue-panel"><div class="section-head"><h2>Revenue Performance</h2><select class="dark-select" id="revenue-range" aria-label="Revenue time range"><option value="6" ${state.revenue==='6'?'selected':''}>Last 6 months</option><option value="3" ${state.revenue==='3'?'selected':''}>Last 3 months</option></select></div><div id="revenue-content">${revenueChart()}</div></section><section class="panel appointments-panel"><div class="section-head"><h2>Upcoming Appointments</h2><span class="badge gray">Demo day</span></div><div class="appointment-list">${appointmentHTML()}</div><a class="text-button" href="#calendar">View full calendar ${I('arrow')}</a></section>${websitePanel()}</div>`;}
function filteredLeads(){return scoped().filter(l=>(state.source==='all'||l.source===state.source)&&(state.service==='all'||l.service===state.service)&&(!state.query||[l.name,l.service,l.city,l.source].some(v=>v.toLowerCase().includes(state.query.toLowerCase())))&&(!state.attention||openStages.includes(l.stage)&&Date.now()-l.stageChanged>3*86400000));}
function trendChart(){const days=state.chart==='weeks'?28:7;const buckets=state.chart==='weeks'?4:7;const counts=Array(buckets).fill(0);scoped().forEach(l=>{const ageDays=Math.floor((Date.now()-l.created)/86400000);if(ageDays>=0&&ageDays<days)counts[buckets-1-Math.floor(ageDays/(days/buckets))]++;});const max=Math.max(...counts,4);const points=counts.map((c,i)=>[24+i*320/(buckets-1),82-c/max*64]);const line='M'+points.map(p=>p.join(',')).join('L');return `<svg class="acquisition-chart" viewBox="0 0 365 112" role="img" aria-label="${counts.join(', ')} new leads across the selected chart periods"><defs><linearGradient id="acq-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b6d64b" stop-opacity=".19"/><stop offset="1" stop-color="#b6d64b" stop-opacity="0"/></linearGradient></defs>${[0,1,2].map(i=>`<line x1="22" x2="348" y1="${82-i*32}" y2="${82-i*32}"/><text x="2" y="${85-i*32}">${Math.round(max*i/2)}</text>`).join('')}<path d="${line}L344,87L24,87Z" fill="url(#acq-fill)"/><path d="${line}" fill="none" stroke="#a5c73b" stroke-width="2.3" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#b1d13b" stroke="white" stroke-width="1.4"><title>${counts[i]} leads</title></circle><text x="${p[0]}" y="106" text-anchor="middle">${state.chart==='weeks'?'Week '+(i+1):new Date(Date.now()-(6-i)*86400000).toLocaleDateString('en-US',{weekday:'short'})}</text>`).join('')}</svg>`;}
function sourceChart(){const items=scoped(),total=items.length;let offset=0;const segments=Object.entries(sourceMeta).map(([name,meta])=>{const count=items.filter(l=>l.source===name).length;const from=offset;offset+=total?count/total*100:0;return {...meta,name,count,from,to:offset};});return `<div class="sources-chart"><div class="donut" style="background:conic-gradient(${segments.map(s=>s.color+' '+s.from+'% '+s.to+'%').join(',')})"><div>${total}<small>Total leads</small></div></div><div class="source-legend">${segments.map(s=>`<div><i style="background:${s.color}"></i>${s.name}<b>${s.count} <span class="muted">· ${total?Math.round(s.count/total*100):0}%</span></b></div>`).join('')}</div></div>`;}
function leadCard(l){return `<article class="lead-card" draggable="true" data-lead-id="${l.id}" data-action="open-lead" data-id="${l.id}" tabindex="0" role="button" aria-label="Open ${esc(l.name)}, ${esc(l.service)}, ${money(l.value)}, from ${esc(l.source)}"><div class="card-source-row">${sourceBadge(l.source)}${I('grip')}</div><h3>${esc(l.name)}</h3><p class="card-service">${esc(l.service)}</p><p class="card-location">${I('pin')}${esc(l.city)}</p><div class="card-value">${money(l.value)}</div><div class="card-next ${openStages.includes(l.stage)&&Date.now()-l.stageChanged>3*86400000?'overdue':''}">${I('clock')}${esc(l.next)}</div><div class="card-bottom"><span class="avatar" title="Assigned to ${esc(l.owner)}">${initials(l.owner)}</span>${l.ai?`<span class="ai-handled">${I('spark')}AI assisted</span>`:''}<span>${age(l)}</span></div></article>`;}
function boardHTML(){const list=filteredLeads();if(state.view==='list')return leadTable(list);return `<div class="board-wrap" id="kanban-scroll"><div class="full-board">${stages.map(s=>{const ls=list.filter(l=>l.stage===s.id);return `<section class="kanban-column" data-drop-stage="${s.id}" style="--stage-color:${s.color}" aria-label="${s.name}"><div class="column-top"><i class="stage-dot"></i><h3>${s.name}</h3><span class="count">${ls.length}</span><button class="icon-button" data-action="add-lead" data-stage="${s.id}" aria-label="Add lead to ${s.name}">${I('plus')}</button></div><p class="column-value"><b>${money(ls.reduce((v,l)=>v+l.value,0))}</b> total value</p>${ls.map(leadCard).join('')}${!ls.length?'<div class="empty-state">No matching leads<br>New opportunities start here.</div>':''}<button class="column-add" data-action="add-lead" data-stage="${s.id}">${I('plus')}Add lead</button></section>`;}).join('')}</div></div>`;}
function leadTable(items){return `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>CLIENT / PROJECT</th><th>SOURCE</th><th>STAGE</th><th>VALUE</th><th>ASSIGNED TO</th><th>NEXT ACTION</th></tr></thead><tbody>${items.map(l=>`<tr data-action="open-lead" data-id="${l.id}" tabindex="0"><td class="table-name">${esc(l.name)}<small>${esc(l.service)}</small></td><td>${sourceBadge(l.source)}</td><td><span class="table-stage" style="--stage-color:${stageFor(l.stage).color}"><i></i>${stageFor(l.stage).name}</span></td><td><b>${money(l.value)}</b></td><td>${esc(l.owner)}</td><td>${esc(l.next)}</td></tr>`).join('')}</tbody></table>${!items.length?'<div class="empty-state">No leads match these filters.</div>':''}</div>`;}
function renderLeads(){const attention=scoped().filter(l=>openStages.includes(l.stage)&&Date.now()-l.stageChanged>3*86400000).length;main.innerHTML=`<div class="page-heading"><div><h1>Every lead. One clear next step.</h1><p>Know where your opportunities come from, what they’re worth, and what needs your attention.</p></div><div class="actions"><select id="period-filter" class="select" aria-label="Metric reporting period"><option value="30" ${state.range==='30'?'selected':''}>Last 30 days</option><option value="7" ${state.range==='7'?'selected':''}>Last 7 days</option><option value="all" ${state.range==='all'?'selected':''}>All time</option></select><button class="btn primary" data-action="add-lead">${I('plus')}Add lead</button></div></div>${metricsHTML()}<div class="leads-analytics"><section class="panel analytics-panel"><div class="section-head"><h2>Lead acquisition</h2><div class="mini-tabs"><button data-action="chart" data-value="weeks" class="${state.chart==='weeks'?'active':''}">4 weeks</button><button data-action="chart" data-value="days" class="${state.chart==='days'?'active':''}">7 days</button></div></div>${trendChart()}</section><section class="panel analytics-panel sources-panel"><div class="section-head"><h2>Where leads come from</h2><span class="badge demo">Attribution</span></div>${sourceChart()}</section><section class="panel analytics-panel attention"><div class="section-head"><h2>Needs a follow-up</h2>${I('clock')}</div><strong>${attention.toString().padStart(2,'0')}</strong><p>Open opportunities with no stage update for over 3 days.</p><button class="text-button" data-action="attention">${state.attention?'Show all leads':'Review these leads'} ${I('arrow')}</button></section></div><div class="pipeline-toolbar"><div class="heading-group"><h2>Your pipeline</h2><span class="pill-label" id="results-count">${filteredLeads().length} opportunities</span></div><div class="filters"><label class="search-field">${I('search')}<input id="lead-search" type="search" value="${esc(state.query)}" placeholder="Search leads…" aria-label="Search leads"></label><select id="source-filter" class="select" aria-label="Filter by source"><option value="all">All sources</option>${Object.keys(sourceMeta).map(s=>`<option ${state.source===s?'selected':''}>${s}</option>`).join('')}</select><select id="service-filter" class="select" aria-label="Filter by service"><option value="all">All services</option>${services.map(s=>`<option ${state.service===s?'selected':''}>${s}</option>`).join('')}</select><div class="view-switch"><button data-action="view" data-value="board" aria-label="Board view" aria-pressed="${state.view==='board'}" class="${state.view==='board'?'active':''}">${I('board')}</button><button data-action="view" data-value="list" aria-label="List view" aria-pressed="${state.view==='list'}" class="${state.view==='list'?'active':''}">${I('list')}</button></div></div></div><div id="board-content">${boardHTML()}</div><div class="board-controls"><span>${I('info')}${state.attention?'Showing follow-ups · Click Review these leads again to clear.':'Drag a card or open it to change stage. Source and AI assistance stay separate.'}</span><div class="board-arrows"><button class="icon-button" data-action="scroll-board" data-direction="-1" aria-label="Scroll pipeline left">${I('left')}</button><button class="icon-button" data-action="scroll-board" data-direction="1" aria-label="Scroll pipeline right">${I('chevron')}</button></div></div>`;}
function renderBoardOnly(){const el=document.querySelector('#board-content');if(el)el.innerHTML=boardHTML();const count=document.querySelector('#results-count');if(count)count.textContent=filteredLeads().length+' opportunities';}
function navigate(page){closeModal();closeMenu();if(location.hash!=='#'+page)location.hash=page;else{currentPage=page;render();}}
function render(){renderSidebar();renderTopbar();document.title=`XAU Prime CRM · ${navItems.find(n=>n[0]===currentPage)?.[1]||'Settings'}`;if(currentPage==='dashboard')renderDashboard();else if(currentPage==='leads')renderLeads();else renderSubpage();}
function subHeading(title,desc,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`;}
function renderSubpage(){
 if(currentPage==='ai-agents'){main.innerHTML=subHeading('A team that keeps things moving.','Explore how calls, messages, estimates, and follow-ups can work together.')+`<div class="preview-strip">These are guided AI demos. No calls, messages, or estimates are sent from this preview.</div><div class="agents-grid">${agentData.map(a=>`<article class="panel agent-large"><span class="agent-icon ${a.cyan?'cyan':''}">${I(a.icon)}</span><h2>${a.name}</h2><p>${a.detail}</p><button class="btn" data-action="agent" data-id="${a.id}">${I('play')}Explore demo ${I('arrow')}</button></article>`).join('')}</div>`;return;}
 if(currentPage==='customers'||currentPage==='projects'){const projects=currentPage==='projects';const items=leads.filter(l=>projects?wonStages.includes(l.stage):!['new_lead','lost'].includes(l.stage));main.innerHTML=subHeading(projects?'From a signed contract to a job well done.':'Your customers, with the full story.',projects?'Active and completed projects stay connected to their original opportunity.':'Contact details, project value, and the next action in one place.')+`<div class="preview-strip">Sample workspace · Open a record to view the client details and move the project forward.</div>`+leadTable(items);return;}
 if(currentPage==='estimates'||currentPage==='documents'||currentPage==='invoices'){const invoice=currentPage==='invoices',doc=currentPage==='documents';const items=leads.filter(l=>invoice?wonStages.includes(l.stage):doc?['contract_signed',...wonStages].includes(l.stage):['estimate_sent','contract_signed',...wonStages].includes(l.stage));main.innerHTML=subHeading(invoice?'Clear invoices. Confident cash flow.':doc?'Every signature. Every next step.':'Build the estimate. Keep the opportunity.',invoice?'Track project billing separately from your sales pipeline.':doc?'Review the agreements attached to your customer projects.':'Review scope and pricing before you send anything to a homeowner.')+`<div class="preview-strip">Design preview · These documents are illustrative. Sending, payments, and legally signed documents require their production integrations.</div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>${invoice?'INVOICE':doc?'DOCUMENT':'ESTIMATE'}</th><th>CUSTOMER</th><th>SERVICE</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>${items.map((l,i)=>`<tr data-action="document" data-id="${l.id}" tabindex="0"><td class="table-name">${invoice?'INV':doc?'DOC':'EST'}-${1048+i}</td><td>${esc(l.name)}</td><td>${esc(l.service)}</td><td><b>${money(l.value)}</b></td><td><span class="badge ${doc?'green':invoice?'amber':'cyan'}">${doc?'Sample contract':invoice?'Draft invoice':l.stage==='estimate_sent'?'Awaiting review':'Accepted · Demo'}</span></td><td>${I('chevron')}</td></tr>`).join('')}</tbody></table></div>`;return;}
 if(currentPage==='calendar'){const d=new Date(),year=d.getFullYear(),month=d.getMonth(),first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();main.innerHTML=subHeading('A more organized day starts here.','Inspections, meetings, and project milestones — together.',`<button class="btn" data-action="calendar-info">${I('calendar')}Calendar connections</button>`)+`<section class="panel"><div class="section-head"><h2>${d.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><span class="badge demo">Sample schedule</span></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(w=>`<div class="calendar-day header">${w}</div>`).join('')}${Array(first).fill('<div class="calendar-day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1;return `<div class="calendar-day ${day===d.getDate()?'today':''}"><span>${day}</span>${[4,9,12,16,20,24,27].includes(day)?`<button class="cal-event" data-action="open-lead" data-id="${appointments[i%3].id}">${appointments[i%3].time}<br>${appointments[i%3].name}<br>${appointments[i%3].task}</button>`:''}</div>`;}).join('')}</div></section>`;return;}
 if(currentPage==='website'){main.innerHTML=subHeading('Your website is part of the system.','See which website inquiries become opportunities in your CRM.')+`<div class="subpage-layout"><div>${websitePanel()}<section class="panel" style="margin-top:16px"><div class="section-head"><h2>Website-sourced opportunities</h2><a href="#leads" class="text-button">View leads ${I('arrow')}</a></div>${leadTable(leads.filter(l=>l.source==='Website'))}</section></div><aside class="info-card"><h3>From first click to next step.</h3><p>Website forms will create a lead with its original source attached. AI assistance, follow-ups, and project progress can then live alongside that record.</p><p style="margin-top:12px">Traffic figures here are sample values. Your analytics and form connections will be configured during implementation.</p><a class="btn" href="https://lizmarconstructionllc.com" target="_blank" rel="noopener">Visit LizMar website ${I('external')}</a></aside></div>`;return;}
 if(currentPage==='messages'){main.innerHTML=subHeading('Every conversation, connected.','Explore how an AI-assisted conversation becomes a well-qualified lead.')+`<div class="subpage-layout"><section class="panel"><div class="section-head"><h2>Demo conversations</h2><span class="badge demo">Not connected</span></div>${agentData.slice(0,2).map(a=>`<button class="agent-tile" data-action="agent" data-id="${a.id}"><span class="agent-icon ${a.cyan?'cyan':''}">${I(a.icon)}</span><span><b>${a.id==='call'?'Sarah Jones · Roof inspection':'Tom Reed · Siding inquiry'}</b><p>${a.desc}</p></span>${I('chevron')}</button>`).join('')}</section><aside class="info-card"><h3>Context that follows the customer.</h3><p>Keep the source, conversation summary, next action, and assigned team member attached to the same lead.</p></aside></div>`;return;}
 if(currentPage==='automations'){main.innerHTML=subHeading('The next step, taken care of.','Preview simple workflows that support your team from inquiry to completion.')+`<div class="agents-grid">${[['New inquiry → fast response','A website lead is captured, the team is notified, and a reply is prepared.','message'],['Estimate sent → thoughtful follow-up','A follow-up is prepared when an estimate has been waiting for three days.','followup'],['Inspection request → booked appointment','The call agent captures the request and helps prepare an inspection slot.','call'],['Spoken scope → reviewed estimate','Turn a spoken project scope into a draft your team reviews before sending.','voice']].map(([title,desc,id])=>`<article class="panel agent-large"><span class="agent-icon">${I('zap')}</span><h2>${title}</h2><p>${desc}</p><button class="btn" data-action="agent" data-id="${id}">Preview workflow ${I('arrow')}</button></article>`).join('')}</div>`;return;}
 if(currentPage==='settings'){main.innerHTML=subHeading('Your workspace. Your way.','Preview preferences and clear information about this design build.')+`<section class="panel"><div class="settings-row"><div><b>Company workspace</b><p>LizMar Construction · Demonstration workspace</p></div><span class="badge demo">Sample</span></div><div class="settings-row"><div><b>Data storage</b><p>Changes to leads are stored only in this browser.</p></div><span class="badge green">${storageAvailable?'Local preview':'Session only'}</span></div><div class="settings-row"><div><b>Reporting window</b><p>Applies to Dashboard and Leads metrics.</p></div><select id="period-filter" class="select" aria-label="Reporting window"><option value="30" ${state.range==='30'?'selected':''}>Last 30 days</option><option value="7" ${state.range==='7'?'selected':''}>Last 7 days</option><option value="all" ${state.range==='all'?'selected':''}>All time</option></select></div><div class="settings-row"><div><b>Restore the sample workspace</b><p>Clears changes you made to the demo leads in this browser.</p></div><button class="btn" data-action="reset-confirm">${I('refresh')}Reset demo</button></div></section>`;return;}
 currentPage='dashboard';renderDashboard();
}
function modal(content,label='Dialog',cls=''){dialogReturnFocus=document.activeElement;document.querySelector('#overlay-root').innerHTML=`<div class="modal-shade" data-modal-shade><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-label="${esc(label)}" tabindex="-1">${content}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>document.querySelector('.dialog input,.dialog select,.dialog button,.dialog')?.focus());}
function closeModal(){document.querySelector('#overlay-root').innerHTML='';document.body.style.overflow='';if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();dialogReturnFocus=null;}
function dialogHead(title,desc=''){return `<div class="dialog-head"><div><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${I('close')}</button></div>`;}
function openLead(id){const l=leads.find(l=>l.id===id);if(!l)return;modal(dialogHead(l.name,l.service+' · '+l.city)+`<div class="lead-detail-hero"><div><div class="eyebrow">Opportunity value</div><strong>${money(l.value)}</strong><p>Original source is retained as this job moves forward.</p></div>${sourceBadge(l.source)}</div><label class="field">Pipeline stage<select id="lead-stage" data-id="${l.id}">${stages.map(s=>`<option value="${s.id}" ${l.stage===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><div class="detail-grid"><div><small>EMAIL</small>${esc(l.email)}</div><div><small>PHONE</small>${esc(l.phone)}</div><div><small>ASSIGNED TO</small>${esc(l.owner)}</div><div><small>PROPERTY</small>${esc(l.address)}<br>${esc(l.city)}</div><div><small>ACQUISITION SOURCE</small>${esc(l.source)}</div><div><small>ASSISTANCE</small>${l.ai?'XØ AI + team':'Team managed'}</div></div><div class="detail-note"><b>Next action</b>${esc(l.next)}</div><h3 style="margin-top:21px">Activity</h3><div class="timeline">${(l.history||[]).slice(-4).reverse().map(h=>`<div><b>${esc(h.text)}</b><p>${new Date(h.at).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · Demo activity</p></div>`).join('')}</div><div class="form-footer"><button class="btn" data-action="edit-lead" data-id="${l.id}">Edit details</button><button class="btn primary" data-action="close-modal">Done ${I('check')}</button></div>`,l.name);}
function leadForm(stage='new_lead',id=null){const l=leads.find(l=>l.id===id);modal(dialogHead(l?'Edit lead':'Add a new lead','Capture the source, assign an owner, and set a clear next step.')+`<form id="lead-form" data-id="${l?.id||''}"><div class="form-grid"><label class="field wide">Client name<input name="name" required maxlength="80" value="${esc(l?.name||'')}" placeholder="e.g. Jordan Taylor" autocomplete="off"></label><label class="field">Email<input name="email" type="email" maxlength="150" value="${esc(l?.email||'')}" placeholder="name@example.com"></label><label class="field">Phone<input name="phone" type="tel" maxlength="35" value="${esc(l?.phone||'')}" placeholder="(401) 555-0100"></label><label class="field">Service<select name="service">${services.map(s=>`<option ${l?.service===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Estimated value ($)<input name="value" type="number" min="0" max="100000000" step="1" required value="${l?.value||''}" placeholder="15000"></label><label class="field">Lead source<select name="source" required><option value="" disabled ${!l?'selected':''}>Select original source</option>${Object.keys(sourceMeta).map(s=>`<option ${l?.source===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Assigned to<select name="owner"><option ${l?.owner==='Bryan Gonzalez'?'selected':''}>Bryan Gonzalez</option><option ${l?.owner==='Sarah Kim'?'selected':''}>Sarah Kim</option></select></label><label class="field">Street address<input name="address" maxlength="150" value="${esc(l?.address||'')}" placeholder="123 Main Street"></label><label class="field">City, state<input name="city" required maxlength="70" value="${esc(l?.city||'')}" placeholder="Warwick, RI"></label><label class="field wide">Stage<select name="stage">${stages.map(s=>`<option value="${s.id}" ${(l?.stage||stage)===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="field wide">Next action<input name="next" required maxlength="150" value="${esc(l?.next||'')}" placeholder="Call to confirm inspection · Tomorrow, 10 AM"></label><label class="field wide">Project notes<textarea name="notes" maxlength="1500" placeholder="Scope, homeowner preferences, and relevant details…">${esc(l?.notes||'')}</textarea></label></div><p class="form-note">Demo data only. This record stays in your browser; no client will be contacted.</p><div class="form-footer"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${I('check')}${l?'Save changes':'Create lead'}</button></div></form>`,l?'Edit lead':'New lead');}
function moveLead(id,stage){const l=leads.find(l=>l.id===id);if(!l||l.stage===stage||!stages.some(s=>s.id===stage))return;const previous=stageFor(l.stage).name;l.stage=stage;l.stageChanged=Date.now();l.next=nextActions[stages.findIndex(s=>s.id===stage)];l.history=l.history||[];l.history.push({text:`Moved from ${previous} to ${stageFor(stage).name}`,at:Date.now()});persist();activities.unshift({text:l.name+' moved to '+stageFor(stage).name,sub:money(l.value)+' · Just now · Demo',icon:'arrow'});render();toast(l.name+' moved to '+stageFor(stage).name);}
function toast(message){clearTimeout(toastTimer);document.querySelector('#toast-root').innerHTML=`<div class="toast">${I('check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>document.querySelector('#toast-root').innerHTML='',4200);}
function openAgent(id){const a=agentData.find(a=>a.id===id)||agentData[0];modal(dialogHead(a.name,a.detail)+`<div class="agent-demo"><div class="eyebrow">Guided example · No live connection</div>${a.id==='call'||a.id==='voice'?`<div class="voice-bars" aria-hidden="true">${'<i></i>'.repeat(32)}</div>`:''}${a.steps.map(([speaker,text])=>`<div class="chat-message ${speaker==='client'?'reply':''}">${esc(text)}<small>${speaker==='agent'?'XØ AI':'Example conversation'}</small></div>`).join('')}</div><div class="agent-summary">${a.summary.map((s,i)=>`<div><b>${s}</b>${['Context','Attribution','Next step'][i]}</div>`).join('')}</div><p class="form-note">This illustrates the intended workflow. Voice, SMS, and AI integrations will be connected during the production build.</p><div class="form-footer"><button class="btn primary" data-action="close-modal">Got it ${I('check')}</button></div>`,a.name);}
function openDocument(id){const l=leads.find(l=>l.id===id);if(!l)return;const invoice=currentPage==='invoices',doc=currentPage==='documents';const materials=Math.round(l.value*.54),labor=l.value-materials;modal(dialogHead(invoice?'Invoice preview':doc?'Agreement preview':'Estimate preview',l.name+' · '+l.service)+`<div class="lead-detail-hero"><div><div class="eyebrow">${doc?'Contract value':'Document total'}</div><strong>${money(l.value)}</strong></div><span class="badge demo">Sample draft</span></div><div class="detail-note"><b>Project scope</b>${esc(l.service)} at ${esc(l.address)}, ${esc(l.city)}.</div>${doc?'<p class="form-note">The signed document workflow will include customer review, signature capture, a timestamped audit trail, and a stored final copy. This preview does not create a legally signed agreement.</p>':`<div class="settings-row"><div>Materials & supplies</div><b>${money(materials)}</b></div><div class="settings-row"><div>Labor & installation</div><b>${money(labor)}</b></div><div class="settings-row"><div>Total</div><b>${money(l.value)}</b></div>`}<div class="form-footer"><button class="btn" data-action="open-lead" data-id="${id}">View client record</button><button class="btn primary" data-action="close-modal">Close preview</button></div>`,doc?'Contract preview':'Document preview');}
function openSearch(){modal(dialogHead('Find your next opportunity','Search names, services, sources, or locations.')+`<input id="global-search" type="search" placeholder="Search your workspace…" aria-label="Search your workspace"><div class="search-results" id="search-results">${searchResults('')}</div>`,'Search workspace','search-dialog');}
function searchResults(q){const found=leads.filter(l=>[l.name,l.service,l.source,l.city].some(s=>s.toLowerCase().includes(q.toLowerCase()))).slice(0,7);return found.length?found.map(l=>`<button class="search-result" data-action="open-lead" data-id="${l.id}"><span>${esc(l.name)}<small>${esc(l.service)} · ${stageFor(l.stage).name}</small></span><span>${money(l.value)}</span></button>`).join(''):'<div class="empty-state">No matching leads. Try another name or service.</div>';}
function closeMenu(){document.querySelector('#sidebar').classList.remove('open');document.querySelector('#scrim').classList.remove('active');}
async function simulate(){if(simulating)return;simulating=true;render();toast('Demo: receiving a new website inquiry…');await new Promise(r=>setTimeout(r,1250));const id='demo-'+Date.now();leads.unshift({id,name:'Jordan Taylor',service:'Roof replacement',city:'Warwick, RI',address:'248 Oak Street',email:'jordan@example.com',phone:'(401) 555-0199',value:16800,stage:'new_lead',source:'Website',ai:true,owner:'Bryan Gonzalez',next:'Review AI summary · Today',notes:'Simulated website inquiry. Homeowner requests an estimate for a roof replacement.',created:Date.now(),stageChanged:Date.now(),history:[{text:'Captured from website form · Simulated event',at:Date.now()},{text:'XØ prepared an inquiry summary · Demo',at:Date.now()}]});persist();activities.unshift({text:'Jordan Taylor requested a roof estimate',sub:'Website → AI assisted · '+money(16800)+' · Demo',icon:'globe'});simulating=false;render();toast('Demo lead added. Your cards, counts, and pipeline value updated.');}
document.addEventListener('click',e=>{
 if(e.target.matches('[data-modal-shade]')){closeModal();return;}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='navigate'){navigate(el.dataset.page);return;}
 if(action==='menu'){document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#scrim').classList.toggle('active');return;}
 if(action==='close-modal'){closeModal();return;}
 if(action==='open-lead'){openLead(el.dataset.id);return;}
 if(action==='add-lead'){leadForm(el.dataset.stage||'new_lead');return;}
 if(action==='edit-lead'){leadForm(undefined,el.dataset.id);return;}
 if(action==='agent'){openAgent(el.dataset.id);return;}
 if(action==='simulate'){simulate();return;}
 if(action==='chart'){state.chart=el.dataset.value;renderLeads();return;}
 if(action==='attention'){state.attention=!state.attention;renderLeads();return;}
 if(action==='view'){state.view=el.dataset.value;renderLeads();return;}
 if(action==='scroll-board'){document.querySelector('#kanban-scroll')?.scrollBy({left:Number(el.dataset.direction)*500,behavior:'smooth'});return;}
 if(action==='search'){openSearch();return;}
 if(action==='document'){openDocument(el.dataset.id);return;}
 if(action==='company'){modal(dialogHead('Your company workspace','You’re exploring a sample workspace for LizMar Construction.')+`<button class="agent-tile" data-action="close-modal"><span class="agent-icon">${I('building')}</span><span><b>LizMar Construction</b><p>Demo workspace · Bryan Gonzalez, admin</p></span>${I('check')}</button><p class="form-note">Company switching and team permissions will use your production company accounts.</p>`,'Company workspace');return;}
 if(action==='notifications'){modal(dialogHead('Workspace activity','The latest events in your demonstration workspace.')+activities.slice(0,7).map(a=>`<div class="activity-item">${I(a.icon)}<div><b>${esc(a.text)}</b><p>${esc(a.sub)}</p></div></div>`).join(''),'Notifications');return;}
 if(action==='calendar-info'){modal(dialogHead('Calendar connections','Bring inspections, appointments, and meetings together.')+`<div class="detail-note"><b>Google Calendar</b>Planned for the production build: calendar connection, appointment sync, conflict checks, and reminders.</div><p class="form-note">This preview uses a sample schedule and does not connect to or change your calendar.</p><div class="form-footer"><button class="btn primary" data-action="close-modal">Got it</button></div>`,'Calendar connections');return;}
 if(action==='reset-confirm'){modal(dialogHead('Restore the sample workspace?','This clears only the demo lead changes saved in this browser.')+`<div class="form-footer"><button class="btn" data-action="close-modal">Keep my changes</button><button class="btn primary" data-action="reset">Reset sample data</button></div>`,'Reset sample data');return;}
 if(action==='reset'){leads=initialLeads();persist();closeModal();state.query='';state.source='all';state.service='all';state.attention=false;render();toast('Sample workspace restored.');}
});
document.addEventListener('input',e=>{if(e.target.id==='lead-search'){state.query=e.target.value;renderBoardOnly();}if(e.target.id==='global-search')document.querySelector('#search-results').innerHTML=searchResults(e.target.value);});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='source-filter'){state.source=el.value;renderBoardOnly();}if(el.id==='service-filter'){state.service=el.value;renderBoardOnly();}if(el.id==='period-filter'){state.range=el.value;render();}if(el.id==='revenue-range'){state.revenue=el.value;document.querySelector('#revenue-content').innerHTML=revenueChart();}if(el.id==='lead-stage'){const id=el.dataset.id;moveLead(id,el.value);openLead(id);}});
document.addEventListener('submit',e=>{if(e.target.id!=='lead-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const id=e.target.dataset.id;const old=leads.find(l=>l.id===id);const value=Number(data.value);if(!data.name.trim()||!sourceMeta[data.source]||!stages.some(s=>s.id===data.stage)||!Number.isFinite(value)||value<0){toast('Enter a name, source, stage, and valid amount.');return;}const changedStage=old&&old.stage!==data.stage;const history=old?.history?[...old.history]:[{text:'Lead created from '+data.source,at:Date.now()}];if(changedStage)history.push({text:'Moved from '+stageFor(old.stage).name+' to '+stageFor(data.stage).name,at:Date.now()});const record={...old,...data,name:data.name.trim(),value,id:id||'lead-'+newRecordId(),ai:old?.ai||data.source==='AI Call',created:old?.created||Date.now(),stageChanged:changedStage?Date.now():old?.stageChanged||Date.now(),history};if(old)leads=leads.map(l=>l.id===id?record:l);else leads.unshift(record);persist();closeModal();render();toast(old?'Lead details updated.':'New lead created in your demo workspace.');});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.lead-card');if(!card)return;dragId=card.dataset.leadId;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId);card.classList.add('dragging');});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-stage]');if(!col||!dragId)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(c=>c.classList.remove('drop-target'));col.classList.add('drop-target');});
document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop-stage]');if(!col||!dragId)return;e.preventDefault();const id=dragId;dragId=null;moveLead(id,col.dataset.dropStage);});
document.addEventListener('dragend',()=>{dragId=null;document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target'));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeMenu();}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action][role="button"],tr[data-action]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&document.querySelector('.dialog')){const focusables=[...document.querySelectorAll('.dialog button,.dialog input,.dialog select,.dialog textarea,.dialog a')].filter(el=>!el.disabled);if(!focusables.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.querySelector('#scrim').addEventListener('click',closeMenu);
window.addEventListener('hashchange',()=>{currentPage=location.hash.slice(1)||'dashboard';closeModal();closeMenu();render();window.scrollTo({top:0});});
render();
